    floatPositionsArr[i * 3] = bx;
    floatPositionsArr[i * 3 + 1] = by;
    floatPositionsArr[i * 3 + 2] = bz;
    floatPhaseArr[i * 3] = Math.random() * Math.PI * 2;
    floatPhaseArr[i * 3 + 1] = Math.random() * Math.PI * 2;
    floatPhaseArr[i * 3 + 2] = Math.random() * Math.PI * 2;
