      var tempoBodyRises = tempoMetrics.map(function (m) { return m.bodyRise || 0; });
      var tempoSnapRises = tempoMetrics.map(function (m) { return m.snapRise || 0; });
      var powerFloor = Math.max(0.001, percentile(tempoPowers, 0.25));
