  if (!id) return;
  var key = customLyricFontKey(id);
  customLyricFonts = (customLyricFonts || []).filter(function (font) { return font && font.id !== id; });
  if (normalizeLyricFontKey(fx.lyricFont) === key || fx.lyricFont === key) fx.lyricFont = 'sans';
